importScripts("https://cdn.jsdelivr.net/pyodide/v0.25.0/full/pyodide.js");

function sendPatch(patch, buffers, msg_id) {
  self.postMessage({
    type: 'patch',
    patch: patch,
    buffers: buffers
  })
}

async function startApplication() {
  console.log("Loading pyodide!");
  self.postMessage({type: 'status', msg: 'Loading pyodide'})
  self.pyodide = await loadPyodide();
  self.pyodide.globals.set("sendPatch", sendPatch);
  console.log("Loaded!");
  await self.pyodide.loadPackage("micropip");
  const env_spec = ['https://tigi-prof-tigi.github.io/tgmaster-afe-python/apps/_vendor/wheels/bokeh-3.4.3-py3-none-any.whl', 'https://tigi-prof-tigi.github.io/tgmaster-afe-python/apps/_vendor/wheels/panel-1.4.5-py3-none-any.whl', 'pyodide-http==0.2.1', 'contextlib', 'html', 'io', 'math', 'pathlib', 'statistics']
  for (const pkg of env_spec) {
    let pkg_name;
    if (pkg.endsWith('.whl')) {
      pkg_name = pkg.split('/').slice(-1)[0].split('-')[0]
    } else {
      pkg_name = pkg
    }
    self.postMessage({type: 'status', msg: `Installing ${pkg_name}`})
    try {
      await self.pyodide.runPythonAsync(`
        import micropip
        await micropip.install('${pkg}');
      `);
    } catch(e) {
      console.log(e)
      self.postMessage({
	type: 'status',
	msg: `Error while installing ${pkg_name}`
      });
    }
  }
  console.log("Packages loaded!");
  self.postMessage({type: 'status', msg: 'Executing code'})
  const code = `
  \nimport asyncio\n\nfrom panel.io.pyodide import init_doc, write_doc\n\ninit_doc()\n\n# === FICHIER GENERE - ne pas editer (voir exercices.py et app.py) ===\n# -*- coding: utf-8 -*-\n"""Banque d'exercices Python : Finance durable et ESG (B3-AFE n\xb018).\n\nTgMaster University.\n\nChaque exercice est un dictionnaire :\n  id        : identifiant court unique\n  seance    : num\xe9ro de s\xe9ance source (alignement avec les .md)\n  titre     : libell\xe9 affich\xe9 dans le menu d\xe9roulant\n  consigne  : \xe9nonc\xe9 en Markdown (donn\xe9es + travail demand\xe9)\n  starter   : code de d\xe9part pr\xe9-rempli dans l'\xe9diteur (avec les donn\xe9es d\xe9j\xe0 saisies)\n  solution  : solution de r\xe9f\xe9rence. Le moteur l'ex\xe9cute UNE fois au d\xe9marrage pour\n              en d\xe9duire les valeurs attendues des variables v\xe9rifi\xe9es. On ne code donc\n              jamais "en dur" un r\xe9sultat : la v\xe9rit\xe9 vient du calcul lui-m\xeame.\n  verifs    : liste de contr\xf4les (variable \xe0 produire, tol\xe9rance absolue, unit\xe9).\n\nCours DESCRIPTIF : pas de TPs Excel, mais des calculs simples int\xe9gr\xe9s aux slides\n(score ESG composite, coupon obligataire et greenium, intensit\xe9 carbone, perte attendue\nclimatique, Sustainability-Linked Bond). Contexte UEMOA / BRVM (BOAD, BIDC-EBID,\nCRRH-UEMOA), entreprises fictives ivoiriennes, montants en FCFA, parit\xe9 655,957.\n"""\n\nEXERCICES = [\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s05_score_esg_composite",\n        "seance": 5,\n        "titre": "S5 \xb7 Score ESG composite pond\xe9r\xe9",\n        "consigne": """\n### Calculer un score ESG composite\n\nUne agence de notation agr\xe8ge les trois piliers E, S et G en un **score composite**, pond\xe9r\xe9\npar la mat\xe9rialit\xe9 sectorielle.\n\nLa soci\xe9t\xe9 fictive **AGRO-CI**, cot\xe9e \xe0 la BRVM, obtient (sur 100) :\n\n| Pilier | Score | Poids sectoriel |\n|--------|-------|-----------------|\n| Environnement (E) | 60 | 0,5 |\n| Social (S) | 80 | 0,3 |\n| Gouvernance (G) | 70 | 0,2 |\n\n**Travail demand\xe9 :** calculer le **score ESG composite** pond\xe9r\xe9 par les poids sectoriels.\n""",\n        "starter": """score_e, score_s, score_g = 60, 80, 70\npoids_e, poids_s, poids_g = 0.5, 0.3, 0.2\n\nscore = ...\n\nprint("score ESG composite =", round(score, 1), "/ 100")\n""",\n        "solution": """\nscore_e, score_s, score_g = 60, 80, 70\npoids_e, poids_s, poids_g = 0.5, 0.3, 0.2\nscore = poids_e * score_e + poids_s * score_s + poids_g * score_g\n""",\n        "verifs": [\n            {"var": "score", "tol": 0.5, "unite": "/100"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s06_coupon_green_bond",\n        "seance": 6,\n        "titre": "S6 \xb7 Coupon d'une obligation verte",\n        "consigne": """\n### Coupon d'une obligation verte (green bond)\n\nUne obligation verte a la **m\xeame m\xe9canique** qu'une obligation classique : seule\nl'affectation des fonds (projets environnementaux) la distingue. La CRRH-UEMOA a \xe9mis un\nsocial bond \xe0 6 % sur la BRVM.\n\n| Param\xe8tre | Valeur |\n|-----------|--------|\n| Nominal | 10 000 FCFA |\n| Taux de coupon annuel | 6 % |\n| Nombre de titres d\xe9tenus | 100 |\n\n**Travail demand\xe9 :**\n1. Calculer le **coupon annuel** par titre.\n2. Calculer le **revenu annuel** d'un investisseur d\xe9tenant 100 titres.\n""",\n        "starter": """nominal = 10000\ntaux_coupon = 0.06\nnb_titres = 100\n\ncoupon = ...\nrevenu_annuel = ...\n\nprint("coupon        =", coupon, "FCFA")\nprint("revenu annuel =", revenu_annuel, "FCFA")\n""",\n        "solution": """\nnominal = 10000\ntaux_coupon = 0.06\nnb_titres = 100\ncoupon = nominal * taux_coupon\nrevenu_annuel = coupon * nb_titres\n""",\n        "verifs": [\n            {"var": "coupon", "tol": 1.0, "unite": "FCFA"},\n            {"var": "revenu_annuel", "tol": 1.0, "unite": "FCFA"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s06_greenium",\n        "seance": 6,\n        "titre": "S6 \xb7 Le greenium (prime verte)",\n        "consigne": """\n### Le greenium : combien l'\xe9metteur \xe9conomise-t-il ?\n\nLe **greenium** est la prime verte : une obligation verte offre un rendement l\xe9g\xe8rement\n**inf\xe9rieur** \xe0 une obligation classique \xe9quivalente (forte demande). Pour l'\xe9metteur, c'est\nun **co\xfbt de financement r\xe9duit**.\n\n| Param\xe8tre | Valeur |\n|-----------|--------|\n| Rendement d'une obligation classique | 6,5 % |\n| Rendement de l'obligation verte | 6,2 % |\n| Montant de l'\xe9mission | 1 000 000 000 FCFA |\n\n**Travail demand\xe9 :**\n1. Calculer le **greenium** (\xe9cart de rendement, en taux).\n2. Calculer l'**\xe9conomie annuelle de co\xfbt** pour l'\xe9metteur.\n""",\n        "starter": """rendement_classique = 0.065\nrendement_vert = 0.062\nmontant_emission = 1_000_000_000\n\ngreenium = ...\neconomie_annuelle = ...\n\nprint("greenium  =", round(greenium * 10000, 1), "points de base")\nprint("\xe9conomie  =", round(economie_annuelle), "FCFA/an")\n""",\n        "solution": """\nrendement_classique = 0.065\nrendement_vert = 0.062\nmontant_emission = 1_000_000_000\ngreenium = rendement_classique - rendement_vert\neconomie_annuelle = montant_emission * greenium\n""",\n        "verifs": [\n            {"var": "greenium", "tol": 0.0005, "unite": ""},\n            {"var": "economie_annuelle", "tol": 1000, "unite": "FCFA"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s08_intensite_carbone",\n        "seance": 8,\n        "titre": "S8 \xb7 Intensit\xe9 carbone d'une entreprise",\n        "consigne": """\n### Mesurer l'intensit\xe9 carbone\n\nL'**intensit\xe9 carbone** rapporte les \xe9missions de gaz \xe0 effet de serre au chiffre d'affaires :\nelle permet de comparer des entreprises de tailles diff\xe9rentes.\n\n| Param\xe8tre | Valeur |\n|-----------|--------|\n| \xc9missions annuelles | 50 000 tCO\u2082 |\n| Chiffre d'affaires | 25 000 millions FCFA |\n\n**Travail demand\xe9 :** calculer l'**intensit\xe9 carbone** (tCO\u2082 par million FCFA de CA).\n""",\n        "starter": """emissions = 50000      # tCO2\nca = 25000             # millions FCFA\n\nintensite = ...\n\nprint("intensit\xe9 carbone =", round(intensite, 2), "tCO2 / M FCFA")\n""",\n        "solution": """\nemissions = 50000\nca = 25000\nintensite = emissions / ca\n""",\n        "verifs": [\n            {"var": "intensite", "tol": 0.01, "unite": "tCO2/M FCFA"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s09_perte_climatique",\n        "seance": 9,\n        "titre": "S9 \xb7 Perte attendue d'un risque climatique",\n        "consigne": """\n### Perte attendue d'un al\xe9a climatique\n\nUne banque mesure la **perte attendue** sur un portefeuille expos\xe9 \xe0 un al\xe9a climatique\n(inondation, s\xe9cheresse) : c'est l'exposition multipli\xe9e par la probabilit\xe9 de survenance.\n\n| Param\xe8tre | Valeur |\n|-----------|--------|\n| Exposition du portefeuille | 20 000 millions FCFA |\n| Probabilit\xe9 de l'al\xe9a sur l'ann\xe9e | 5 % |\n\n**Travail demand\xe9 :** calculer la **perte attendue**.\n""",\n        "starter": """exposition = 20000     # millions FCFA\nprobabilite = 0.05\n\nperte_attendue = ...\n\nprint("perte attendue =", perte_attendue, "millions FCFA")\n""",\n        "solution": """\nexposition = 20000\nprobabilite = 0.05\nperte_attendue = exposition * probabilite\n""",\n        "verifs": [\n            {"var": "perte_attendue", "tol": 0.5, "unite": "M FCFA"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s09_prime_risque_climatique",\n        "seance": 9,\n        "titre": "S9 \xb7 Prime de risque climatique sur le taux exig\xe9",\n        "consigne": """\n### Int\xe9grer une prime de risque climatique au taux exig\xe9\n\nPour r\xe9mun\xe9rer l'exposition \xe0 un al\xe9a climatique, le pr\xeateur ajoute une **prime de risque\nclimatique** au taux de base.\n\n| Param\xe8tre | Valeur |\n|-----------|--------|\n| Taux de base | 6 % |\n| Prime de risque climatique | 1,5 % |\n| Nominal du pr\xeat | 10 000 FCFA |\n\n**Travail demand\xe9 :**\n1. Calculer le **taux exig\xe9** (taux de base augment\xe9 de la prime).\n2. Calculer le **surco\xfbt annuel** d'int\xe9r\xeat d\xfb \xe0 la prime, sur le nominal.\n""",\n        "starter": """taux_base = 0.06\nprime_clim = 0.015\nnominal = 10000\n\ntaux_exige = ...\nsurcout = ...\n\nprint("taux exig\xe9 =", round(taux_exige * 100, 2), "%")\nprint("surco\xfbt    =", surcout, "FCFA/an")\n""",\n        "solution": """\ntaux_base = 0.06\nprime_clim = 0.015\nnominal = 10000\ntaux_exige = taux_base + prime_clim\nsurcout = nominal * prime_clim\n""",\n        "verifs": [\n            {"var": "taux_exige", "tol": 0.0005, "unite": ""},\n            {"var": "surcout", "tol": 1.0, "unite": "FCFA"},\n        ],\n    },\n\n    # ================================================================== #\n    #  TIER AVANCE : exercices multi-\xe9tapes (boucles, listes, d\xe9cision). #\n    #  Niveau MBA / \u2605\u2605\u2605.                                                 #\n    # ================================================================== #\n    {\n        "id": "adv_screening_esg",\n        "seance": 7,\n        "niveau": "avance",\n        "titre": "A1 \xb7 Screening ISR d'un portefeuille par score ESG",\n        "consigne": """\n### Filtrer un univers d'investissement (best-in-class)\n\nUne strat\xe9gie ISR *best-in-class* ne retient que les \xe9metteurs dont le score ESG composite\natteint un **seuil minimal de 50/100**. Poids des piliers : **E 0,4 / S 0,3 / G 0,3**.\n\n| \xc9metteur (fictif BRVM) | E | S | G |\n|------------------------|----|----|----|\n| Solibra | 40 | 70 | 80 |\n| SIFCA | 30 | 60 | 55 |\n| Orange CI | 75 | 80 | 85 |\n| PALMCI | 35 | 45 | 40 |\n\n**Travail demand\xe9 :** parcourir les \xe9metteurs, calculer le score composite de chacun, puis :\n1. compter combien sont **retenus** (score >= 50).\n2. retenir le **meilleur score** de l'univers.\n""",\n        "starter": """poids_e, poids_s, poids_g = 0.4, 0.3, 0.3\nemetteurs = [\n    {"nom": "Solibra",  "E": 40, "S": 70, "G": 80},\n    {"nom": "SIFCA",    "E": 30, "S": 60, "G": 55},\n    {"nom": "Orange CI","E": 75, "S": 80, "G": 85},\n    {"nom": "PALMCI",   "E": 35, "S": 45, "G": 40},\n]\n\nnb_retenus = 0\nscore_max = 0.0\nfor e in emetteurs:\n    score = ...\n    if score >= 50:\n        nb_retenus = nb_retenus + 1\n    if score > score_max:\n        score_max = ...\n\nprint("\xe9metteurs retenus =", nb_retenus)\nprint("meilleur score    =", round(score_max, 1))\n""",\n        "solution": """\npoids_e, poids_s, poids_g = 0.4, 0.3, 0.3\nemetteurs = [\n    {"nom": "Solibra",  "E": 40, "S": 70, "G": 80},\n    {"nom": "SIFCA",    "E": 30, "S": 60, "G": 55},\n    {"nom": "Orange CI","E": 75, "S": 80, "G": 85},\n    {"nom": "PALMCI",   "E": 35, "S": 45, "G": 40},\n]\nnb_retenus = 0\nscore_max = 0.0\nfor e in emetteurs:\n    score = poids_e * e["E"] + poids_s * e["S"] + poids_g * e["G"]\n    if score >= 50:\n        nb_retenus = nb_retenus + 1\n    if score > score_max:\n        score_max = score\n""",\n        "verifs": [\n            {"var": "nb_retenus", "tol": 0.5, "unite": ""},\n            {"var": "score_max", "tol": 0.5, "unite": "/100"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "adv_slb_coupon",\n        "seance": 6,\n        "niveau": "avance",\n        "titre": "A2 \xb7 Sustainability-Linked Bond : coupon index\xe9 (step-up)",\n        "consigne": """\n### Le coupon d'un SLB monte si l'objectif ESG est rat\xe9\n\nUn **Sustainability-Linked Bond (SLB)** indexe son coupon sur l'atteinte d'un objectif ESG :\nsi le KPI n'est **pas** atteint une ann\xe9e, un **step-up** de +0,25 % s'applique cette\nann\xe9e-l\xe0.\n\n| Param\xe8tre | Valeur |\n|-----------|--------|\n| Nominal | 100 000 000 FCFA |\n| Coupon de base | 6 % |\n| Step-up si KPI rat\xe9 | +0,25 % |\n\nL'\xe9metteur atteint son KPI les **2 premi\xe8res ann\xe9es**, puis le rate les **3 derni\xe8res** :\n\`kpi_atteint = [True, True, False, False, False]\`.\n\n**Travail demand\xe9 :** parcourir les 5 ann\xe9es, d\xe9terminer le taux de coupon de chaque ann\xe9e\n(base si atteint, base augment\xe9e du step-up sinon), puis :\n1. calculer le **total des coupons** vers\xe9s sur 5 ans.\n2. calculer le **surco\xfbt total** d\xfb aux step-up.\n""",\n        "starter": """nominal = 100_000_000\ncoupon_base = 0.06\nstep_up = 0.0025\nkpi_atteint = [True, True, False, False, False]\n\ntotal_coupons = 0.0\nsurcout = 0.0\nfor atteint in kpi_atteint:\n    if atteint:\n        taux = coupon_base\n    else:\n        taux = ...\n        surcout = surcout + nominal * step_up\n    total_coupons = total_coupons + nominal * taux\n\nprint("total coupons =", round(total_coupons))\nprint("surco\xfbt total =", round(surcout))\n""",\n        "solution": """\nnominal = 100_000_000\ncoupon_base = 0.06\nstep_up = 0.0025\nkpi_atteint = [True, True, False, False, False]\ntotal_coupons = 0.0\nsurcout = 0.0\nfor atteint in kpi_atteint:\n    if atteint:\n        taux = coupon_base\n    else:\n        taux = coupon_base + step_up\n        surcout = surcout + nominal * step_up\n    total_coupons = total_coupons + nominal * taux\n""",\n        "verifs": [\n            {"var": "total_coupons", "tol": 1000, "unite": "FCFA"},\n            {"var": "surcout", "tol": 1000, "unite": "FCFA"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "adv_greenium_va",\n        "seance": 6,\n        "niveau": "avance",\n        "titre": "A3 \xb7 Valeur actuelle de l'\xe9conomie du greenium",\n        "consigne": """\n### Combien vaut le greenium sur toute la maturit\xe9 ?\n\nLe greenium fait \xe9conomiser un peu d'int\xe9r\xeat **chaque ann\xe9e**. Pour mesurer son int\xe9r\xeat\n\xe9conomique total, on **actualise** ces \xe9conomies sur la maturit\xe9 de l'obligation.\n\n| Param\xe8tre | Valeur |\n|-----------|--------|\n| Greenium | 0,3 % |\n| Montant de l'\xe9mission | 1 000 000 000 FCFA |\n| Maturit\xe9 | 7 ans |\n| Taux d'actualisation | 6 % |\n\n**Travail demand\xe9 :**\n1. Calculer l'**\xe9conomie annuelle**.\n2. Dans la boucle, **cumuler la valeur actuelle** de cette \xe9conomie sur 7 ans\n(VA d'un flux de l'ann\xe9e t = flux / (1 + taux)^t).\n""",\n        "starter": """greenium = 0.003\nmontant = 1_000_000_000\nmaturite = 7\ntaux_actu = 0.06\n\neconomie_annuelle = ...\n\nva_economies = 0.0\nfor t in range(1, maturite + 1):\n    va_economies = va_economies + ...\n\nprint("\xe9conomie annuelle =", round(economie_annuelle))\nprint("VA des \xe9conomies  =", round(va_economies))\n""",\n        "solution": """\ngreenium = 0.003\nmontant = 1_000_000_000\nmaturite = 7\ntaux_actu = 0.06\neconomie_annuelle = montant * greenium\nva_economies = 0.0\nfor t in range(1, maturite + 1):\n    va_economies = va_economies + economie_annuelle / (1 + taux_actu) ** t\n""",\n        "verifs": [\n            {"var": "economie_annuelle", "tol": 1000, "unite": "FCFA"},\n            {"var": "va_economies", "tol": 100_000, "unite": "FCFA"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "adv_empreinte_portefeuille",\n        "seance": 8,\n        "niveau": "avance",\n        "titre": "A4 \xb7 Empreinte carbone pond\xe9r\xe9e d'un portefeuille",\n        "consigne": """\n### Intensit\xe9 carbone moyenne pond\xe9r\xe9e d'un portefeuille\n\nL'empreinte carbone d'un portefeuille est la **moyenne des intensit\xe9s carbone** de ses\npositions, **pond\xe9r\xe9e par leur poids**. On rep\xe8re aussi les positions trop intensives\n(intensit\xe9 sup\xe9rieure \xe0 3 tCO\u2082/M FCFA).\n\n| Position | Poids | Intensit\xe9 (tCO\u2082/M FCFA) |\n|----------|-------|--------------------------|\n| \xc9nergie Solaire Bamba | 0,5 | 2,0 |\n| BTP Kouassi | 0,3 | 5,0 |\n| Transports Diallo | 0,2 | 1,0 |\n\n**Travail demand\xe9 :** parcourir les positions, puis :\n1. calculer l'**intensit\xe9 carbone du portefeuille** (moyenne pond\xe9r\xe9e, somme des poids \xd7 intensit\xe9).\n2. compter les positions **au-dessus du seuil** de 3.\n""",\n        "starter": """positions = [\n    {"nom": "\xc9nergie Solaire Bamba", "poids": 0.5, "intensite": 2.0},\n    {"nom": "BTP Kouassi",           "poids": 0.3, "intensite": 5.0},\n    {"nom": "Transports Diallo",     "poids": 0.2, "intensite": 1.0},\n]\nseuil = 3.0\n\nintensite_pf = 0.0\nnb_au_dessus = 0\nfor p in positions:\n    intensite_pf = intensite_pf + ...\n    if p["intensite"] > seuil:\n        nb_au_dessus = nb_au_dessus + 1\n\nprint("intensit\xe9 portefeuille =", round(intensite_pf, 2), "tCO2 / M FCFA")\nprint("positions > seuil      =", nb_au_dessus)\n""",\n        "solution": """\npositions = [\n    {"nom": "\xc9nergie Solaire Bamba", "poids": 0.5, "intensite": 2.0},\n    {"nom": "BTP Kouassi",           "poids": 0.3, "intensite": 5.0},\n    {"nom": "Transports Diallo",     "poids": 0.2, "intensite": 1.0},\n]\nseuil = 3.0\nintensite_pf = 0.0\nnb_au_dessus = 0\nfor p in positions:\n    intensite_pf = intensite_pf + p["poids"] * p["intensite"]\n    if p["intensite"] > seuil:\n        nb_au_dessus = nb_au_dessus + 1\n""",\n        "verifs": [\n            {"var": "intensite_pf", "tol": 0.01, "unite": "tCO2/M FCFA"},\n            {"var": "nb_au_dessus", "tol": 0.5, "unite": ""},\n        ],\n    },\n]\n\n\ndef exercice_par_id(eid):\n    for ex in EXERCICES:\n        if ex["id"] == eid:\n            return ex\n    return None\n\n\n# === app.py ===\n# -*- coding: utf-8 -*-\n"""App Panel - Exercices Python interactifs\nFinance durable et ESG (B3-AFE n\xb018)\nTgMaster University.\n\nL'etudiant ecrit son code dans l'editeur, clique "Verifier", et l'app :\n  1. execute le code (sortie texte capturee),\n  2. compare la VALEUR des variables attendues a la solution de reference,\n     avec une tolerance numerique (robuste : pas de comparaison de chaines).\n\nLancement local :\n    pip install panel\n    panel serve app.py --show\n\nDeploiement (voir README.md) :\n    - Hugging Face Spaces (Docker) ou Railway  -> mode serveur\n    - panel convert app.py --to pyodide-worker  -> HTML statique (zero serveur),\n      a embarquer dans Moodle via une iframe.\n"""\nimport io\nimport contextlib\nimport math\nimport pathlib\nimport statistics\n\nimport panel as pn\n\n\n# --- Habillage "Navy TgMaster" (custom_panel.css place a cote de ce fichier) ---\n# CSS inline (compatible Pyodide, aucune lecture de fichier au runtime)\n_RAW_CSS = [r'''\n/* ===========================================================================\n   custom_panel.css - Habillage "Navy TgMaster" pour l'app Panel (app.py)\n   \xc0 placer \xe0 c\xf4t\xe9 de app.py. Charg\xe9 automatiquement par app.py (voir ce fichier).\n   Pour changer de direction visuelle : modifier les 6 variables de :root.\n   =========================================================================== */\n@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=DM+Serif+Display:ital@0;1&family=JetBrains+Mono:wght@400;500;600&display=swap');\n\n:root {\n  --accent:        #03224C;\n  --accent-strong: #001A3D;\n  --accent-soft:   #E7ECF3;\n  --red:           #BD362F;\n  --page-bg:       #F5F0E5;\n  --surface:       #ffffff;\n  --surface-2:     #FAF6EE;\n  --border:        #E6DECF;\n  --border-strong: #D6CBB6;\n  --text:          #11203A;\n  --text-muted:    #5B647E;\n  --success:       #1F8A4C;\n  --danger:        #C82020;\n  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;\n  --font-serif: 'DM Serif Display', Georgia, serif;\n  --font-mono: 'JetBrains Mono', ui-monospace, Menlo, Consolas, monospace;\n}\n\nbody, .bk-root {\n  font-family: var(--font-sans) !important;\n  color: var(--text);\n  background: var(--page-bg) !important;\n  font-size: 15px !important;\n}\n.bk-root .bk-Column { background: transparent; }\n\n/* S\xe9lecteur d'exercice */\nselect.bk-input, .bk-input {\n  font-family: var(--font-sans) !important;\n  border: 1px solid var(--border-strong) !important;\n  border-radius: 8px !important;\n  color: var(--text) !important;\n  background: var(--surface) !important;\n  font-weight: 600;\n  padding: 9px 12px !important;\n}\nselect.bk-input:focus, .bk-input:focus {\n  outline: none !important;\n  border-color: var(--accent) !important;\n  box-shadow: 0 0 0 3px rgba(3,34,76,0.20) !important;\n}\n.bk-input-group label, label.bk {\n  font-weight: 600 !important;\n  color: var(--text-muted) !important;\n  font-size: 12px !important;\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n}\n\n/* Boutons */\n.bk-btn {\n  font-family: var(--font-sans) !important;\n  font-weight: 600 !important;\n  border-radius: 8px !important;\n  padding: 9px 16px !important;\n  border: 1px solid transparent !important;\n  transition: background .15s ease, color .15s ease;\n}\n.bk-btn-primary { background: var(--accent) !important; border-color: var(--accent) !important; color: #fff !important; }\n.bk-btn-primary:hover { background: var(--accent-strong) !important; }\n.bk-btn-default { background: var(--surface) !important; color: var(--text-muted) !important; border-color: var(--border-strong) !important; }\n.bk-btn-default:hover { background: var(--surface-2) !important; color: var(--text) !important; }\n.bk-btn-warning { background: transparent !important; color: var(--accent-strong) !important; border-color: var(--border-strong) !important; }\n.bk-btn-warning:hover { background: var(--accent-soft) !important; }\n.bk-btn-warning.bk-active { background: var(--accent-soft) !important; border-color: var(--accent) !important; }\n\n/* \xc9diteur de code (Ace) */\n.bk-root .ace_editor {\n  border: 1px solid var(--border) !important;\n  border-radius: 12px !important;\n  font-family: var(--font-mono) !important;\n  box-shadow: 0 1px 2px rgba(20,26,50,0.06);\n  overflow: hidden;\n}\n\n/* \xc9nonc\xe9 + feedback (panes Markdown) - plats, sans carte (les cartes sont g\xe9r\xe9es par .main-panel) */\n.bk-root .markdown { line-height: 1.66; font-size: 16px; color: #20304d; }\n.bk-root .markdown h3 { font-family: var(--font-serif); font-weight: 400; font-size: 21px; color: var(--accent); margin: 2px 0 10px; }\n.bk-root .markdown p { margin: 8px 0; }\n.bk-root .markdown strong { color: var(--accent); }\n.bk-root .markdown ol, .bk-root .markdown ul { padding-left: 22px; }\n.bk-root .markdown li { margin: 5px 0; }\n.bk-root .markdown h3 { color: var(--text); font-weight: 800; }\n.bk-root .markdown code {\n  font-family: var(--font-mono) !important;\n  background: var(--accent-soft);\n  color: var(--accent-strong);\n  padding: 1.5px 6px; border-radius: 5px; font-size: 0.86em;\n}\n.bk-root .markdown table {\n  border-collapse: separate; border-spacing: 0;\n  border: 1px solid var(--border-strong); border-radius: 10px; overflow: hidden;\n  box-shadow: 0 1px 3px rgba(3,34,76,.07); margin: 10px 0;\n}\n.bk-root .markdown th {\n  background: var(--accent); color: #fff; text-align: left; font-weight: 700;\n  padding: 11px 15px !important; border-bottom: none;\n}\n.bk-root .markdown td {\n  padding: 10px 15px !important; border-bottom: 1px solid var(--border);\n  font-variant-numeric: tabular-nums; font-size: 15px;\n}\n.bk-root .markdown tr:nth-child(even) td { background: var(--surface-2); }\n\n.bk-root hr { border: none; border-top: 1px solid var(--border); margin: 6px 0; }\n\n/* =========================================================================\n   LAYOUT MAQUETTE - header + progression / sidebar cartes / panneau + \xe9diteur\n   ========================================================================= */\n\n/* --- En-t\xeate gradient + barre de progression --- */\n.app-header {\n  background: linear-gradient(100deg, var(--accent-strong), var(--accent)) !important;\n  border-radius: 16px !important;\n  padding: 18px 26px !important;\n  box-shadow: 0 8px 24px rgba(20,26,50,.14);\n  align-items: center !important;\n}\n.hdr-sub {\n  color: rgba(255,255,255,.78); font-size: 12.5px; font-weight: 600;\n  letter-spacing: .06em; text-transform: uppercase;\n}\n.hdr-title {\n  color: #fff; font-family: var(--font-serif); font-size: 25px; font-weight: 400; letter-spacing: 0; margin-top: 4px;\n}\n.prog-wrap { text-align: right; min-width: 200px; }\n.prog-pill {\n  color: #fff; font-size: 13px; font-weight: 700; margin-bottom: 7px;\n}\n.prog-track {\n  width: 200px; height: 9px; border-radius: 99px;\n  background: rgba(255,255,255,.22); overflow: hidden; margin-left: auto;\n}\n.prog-fill {\n  height: 100%; border-radius: 99px; background: #fff;\n  transition: width .35s ease;\n}\n\n/* --- Sidebar \xab Parcours d'exercices \xbb --- */\n.sidebar {\n  background: var(--surface); border: 1px solid var(--border);\n  border-radius: 16px; padding: 16px 14px !important;\n  box-shadow: 0 1px 2px rgba(20,26,50,.06);\n}\n.sb-title { font-size: 15.5px; font-weight: 800; color: var(--text); }\n.sb-sub { font-size: 12.5px; color: var(--text-muted); margin-top: 1px; margin-bottom: 6px; }\n.section-head {\n  font-size: 11.5px; font-weight: 700; color: var(--text-muted);\n  letter-spacing: .07em; text-transform: uppercase;\n  margin: 14px 6px 6px;\n}\n\n/* Carte exercice = Row [badge | bouton-label | statut] */\n.exo-card {\n  align-items: center !important;\n  flex-wrap: nowrap !important;\n  overflow: hidden !important;\n  border: 1px solid var(--border) !important;\n  border-radius: 11px !important;\n  margin-bottom: 7px !important;\n  padding: 4px 8px !important;\n  background: var(--surface) !important;\n  transition: border-color .15s ease, background .15s ease, box-shadow .15s ease;\n}\n.exo-card:hover { border-color: var(--border-strong) !important; background: var(--surface-2) !important; }\n.exo-card.actif {\n  border-color: var(--accent) !important;\n  background: var(--accent-soft) !important;\n  box-shadow: 0 0 0 3px rgba(3,34,76,.15) !important;\n}\n/* TOUS les enfants flex doivent pouvoir r\xe9tr\xe9cir sous la largeur de leur contenu */\n.exo-card > * { min-width: 0 !important; }\n/* Badge (gauche) et pastille (droite) : taille fixe, ne r\xe9tr\xe9cissent pas */\n.exo-card > *:first-child { flex: 0 0 auto !important; }\n.exo-card > *:last-child  { flex: 0 0 auto !important; }\n/* Le bouton-label au milieu : prend l'espace restant et r\xe9tr\xe9cit */\n.exo-card > *:nth-child(2) { flex: 1 1 auto !important; min-width: 0 !important; }\n\n.exo-badge-sb {\n  font-family: var(--font-mono) !important; font-size: 12.5px; font-weight: 700;\n  color: var(--accent); background: var(--accent-soft);\n  border: 1px solid var(--border); border-radius: 7px;\n  padding: 4px 7px; min-width: 34px; text-align: center;\n}\n.exo-card.actif .exo-badge-sb { background: #fff; }\n/* Le bouton-label occupe l'espace, transparent et sans bordure, texte tronqu\xe9 proprement */\n.exo-card .bk-btn, .exo-card .bk-btn-default {\n  background: transparent !important; border: none !important; box-shadow: none !important;\n  text-align: left !important; color: var(--text) !important;\n  font-weight: 600 !important; font-size: 14px !important;\n  padding: 6px 4px !important; line-height: 1.4 !important;\n  min-width: 0 !important; width: 100% !important; max-width: 100% !important;\n  display: block !important;\n  white-space: nowrap !important; overflow: hidden !important; text-overflow: ellipsis !important;\n}\n.exo-card .bk-btn:hover { background: transparent !important; color: var(--accent-strong) !important; }\n.exo-stat {\n  flex: 0 0 auto; width: 20px; height: 20px; border-radius: 99px;\n  border: 2px solid var(--border-strong);\n  display: flex; align-items: center; justify-content: center;\n  font-size: 12px; color: transparent;\n}\n.exo-card.ok .exo-stat {\n  border-color: var(--success); background: var(--success); color: #fff;\n}\n\n/* --- Panneau principal --- */\n.main-panel {\n  background: var(--surface); border: 1px solid var(--border);\n  border-radius: 16px; padding: 22px 26px !important;\n  box-shadow: 0 1px 2px rgba(20,26,50,.06);\n}\n.exo-head { align-items: center !important; }\n.exo-badge {\n  font-family: var(--font-mono) !important; font-weight: 800; font-size: 15px;\n  color: #fff; background: var(--accent); border-radius: 9px;\n  padding: 7px 11px; margin-right: 4px;\n}\n.exo-h-title { font-family: var(--font-serif); font-size: 24px; font-weight: 400; color: var(--text); letter-spacing: 0; }\n.tag-base, .tag-avance {\n  font-size: 10.5px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase;\n  padding: 4px 9px; border-radius: 99px;\n}\n.tag-base { color: var(--accent-strong); background: var(--accent-soft); }\n.tag-avance { color: #fff; background: linear-gradient(100deg, var(--accent-strong), var(--accent)); }\n\n/* --- Fen\xeatre \xe9diteur style macOS --- */\n.editor-window {\n  border: 1px solid var(--border-strong) !important;\n  border-radius: 12px !important; overflow: hidden;\n  box-shadow: 0 6px 18px rgba(20,26,50,.10);\n  background: #fbfbfd;\n}\n.editor-titlebar {\n  display: flex; align-items: center; gap: 9px;\n  background: var(--surface-2); border-bottom: 1px solid var(--border);\n  padding: 8px 13px;\n}\n.editor-titlebar .dot { width: 12px; height: 12px; border-radius: 99px; display: inline-block; }\n.dot-r { background: #ec6a5e; } .dot-y { background: #f4be4f; } .dot-g { background: #61c554; }\n.editor-titlebar .fname {\n  font-family: var(--font-mono) !important; font-size: 12px; color: var(--text-muted);\n  margin-left: 6px;\n}\n.editor-window .ace_editor { border: none !important; border-radius: 0 !important; box-shadow: none !important; }\n\n/* --- Carte feedback --- */\n.feedback-card {\n  background: var(--surface-2); border: 1px solid var(--border);\n  border-radius: 12px; padding: 6px 18px !important; margin-top: 4px !important;\n}\n\n/* --- Corps deux colonnes responsive --- */\n.body-row { align-items: flex-start !important; flex-wrap: wrap !important; gap: 16px; }\n.body-row > div { min-width: 0 !important; }\n.sidebar { flex: 0 0 280px !important; }\n.main-panel { flex: 1 1 420px !important; min-width: 0 !important; }\n/* Sur \xe9cran \xe9troit : la sidebar passe pleine largeur au-dessus du panneau */\n@media (max-width: 820px) {\n  .sidebar { flex-basis: 100% !important; }\n}\n\n.consigne { background: var(--surface-2); border: 1px solid var(--border); border-left: 4px solid var(--accent); border-radius: 12px; padding: 16px 22px !important; margin: 4px 0 10px; }\n''']\n\npn.extension("codeeditor", sizing_mode="stretch_width", raw_css=_RAW_CSS)\n\n# Palette de la maquette (Navy TgMaster)\nNAVY = "#03224C"   # navy site (titres, messages neutres)\nRED = "#C82020"    # erreurs\nGREEN = "#1b8a52"  # succes\n\n# Environnement d'execution autorise : modules surs pour du calcul financier.\nSAFE_MODULES = {"math": math, "statistics": statistics}\n\n\n# --------------------------------------------------------------------------- #\n# Moteur d'execution et de verification\n# --------------------------------------------------------------------------- #\ndef executer_code(code):\n    """Execute \`code\` dans un espace de noms neuf.\n    Retourne (namespace, sortie_texte, erreur_ou_None).\n    Pas de subprocess -> compatible Pyodide (WASM, execution dans le navigateur).\n    """\n    ns = dict(SAFE_MODULES)\n    sortie = io.StringIO()\n    erreur = None\n    try:\n        with contextlib.redirect_stdout(sortie):\n            exec(code, ns)  # noqa: S102 - outil pedagogique, execution voulue\n    except Exception as exc:  # noqa: BLE001\n        erreur = f"{type(exc).__name__} : {exc}"\n    return ns, sortie.getvalue(), erreur\n\n\n# Valeurs de reference : calculees UNE fois depuis la solution de chaque exercice.\ndef _valeurs_attendues(ex):\n    ns, _, err = executer_code(ex["solution"])\n    if err:\n        raise RuntimeError(f"Solution invalide pour {ex['id']} : {err}")\n    return {v["var"]: ns[v["var"]] for v in ex["verifs"]}\n\n\nATTENDU = {ex["id"]: _valeurs_attendues(ex) for ex in EXERCICES}\n\n\ndef verifier(ex, code):\n    """Renvoie (ok_global, markdown_feedback)."""\n    # Garde-fou pedagogique : tant qu'il reste des "..." (placeholders a completer),\n    # on ne lance pas le code -> on evite un TypeError cryptique sur Ellipsis.\n    lignes_a_completer = [i for i, ligne in enumerate(code.splitlines(), start=1)\n                          if "..." in ligne]\n    if lignes_a_completer:\n        nums = ", ".join(str(n) for n in lignes_a_completer)\n        return False, (f"<span style='color:{NAVY}'>\u270f\ufe0f Il reste des \`...\` \xe0 "\n                       f"compl\xe9ter (ligne(s) {nums}). Remplace chaque \`...\` par "\n                       f"ta formule, puis clique de nouveau sur "\n                       f"<b>V\xe9rifier</b>.</span>")\n\n    ns, sortie, erreur = executer_code(code)\n\n    lignes = []\n    if sortie.strip():\n        lignes.append("**Sortie de ton code :**")\n        lignes.append("\`\`\`\\n" + sortie.rstrip() + "\\n\`\`\`")\n\n    if erreur:\n        lignes.append(f"<span style='color:{RED}'>\u274c **Erreur d'ex\xe9cution :** "\n                      f"{erreur}</span>")\n        return False, "\\n\\n".join(lignes)\n\n    attendu = ATTENDU[ex["id"]]\n    tous_ok = True\n    details = []\n    for v in ex["verifs"]:\n        nom = v["var"]\n        unite = (" " + v["unite"]) if v["unite"] else ""\n        if nom not in ns or ns[nom] is Ellipsis:\n            tous_ok = False\n            details.append(f"<span style='color:{RED}'>\u274c \`{nom}\` n'est pas "\n                           f"encore calcul\xe9 (il vaut \`...\`).</span>")\n            continue\n        try:\n            val = float(ns[nom])\n        except (TypeError, ValueError):\n            tous_ok = False\n            details.append(f"<span style='color:{RED}'>\u274c \`{nom}\` doit \xeatre un "\n                           f"nombre.</span>")\n            continue\n        ref = float(attendu[nom])\n        if abs(val - ref) <= v["tol"]:\n            details.append(f"<span style='color:{GREEN}'>\u2705 \`{nom}\` = "\n                           f"{_fmt(val)}{unite}</span>")\n        else:\n            tous_ok = False\n            details.append(f"<span style='color:{RED}'>\u274c \`{nom}\` = {_fmt(val)}"\n                           f"{unite} : ce n'est pas la valeur attendue.</span>")\n\n    lignes.append("\\n".join(details))\n    if tous_ok:\n        lignes.append(f"<h3 style='color:{GREEN}'>\U0001f389 Exercice r\xe9ussi, "\n                      f"bravo !</h3>")\n    else:\n        lignes.append(f"<span style='color:{NAVY}'>V\xe9rifie tes formules et "\n                      f"r\xe9essaie.</span>")\n    return tous_ok, "\\n\\n".join(lignes)\n\n\ndef _fmt(x):\n    """Affichage lisible : entier si rond, sinon 4 decimales max."""\n    if abs(x - round(x)) < 1e-9:\n        return f"{int(round(x))}"\n    return f"{x:.4f}".rstrip("0").rstrip(".")\n\n\n# --------------------------------------------------------------------------- #\n# Interface - maquette : en-tete + progression / sidebar cartes / panneau editeur\n# --------------------------------------------------------------------------- #\nimport html as _html\n\nTOTAL = len(EXERCICES)\nsolved = set()                       # ids des exercices reussis\netat = {"id": EXERCICES[0]["id"]}     # exercice courant\n\n\ndef _split_titre(titre):\n    """'A1 \xb7 Obligation - trouver le YTM' -> ('A1', 'Obligation - trouver le YTM').\n    'Exercice 1 \xb7 ...' garde le badge tel quel ; sinon numerote."""\n    if "\xb7" in titre:\n        badge, label = titre.split("\xb7", 1)\n        return badge.strip(), label.strip()\n    return "", titre.strip()\n\n\n# --- Widgets de contenu ----------------------------------------------------- #\nconsigne = pn.pane.Markdown(sizing_mode="stretch_width", css_classes=["consigne"])\nediteur = pn.widgets.CodeEditor(language="python", theme="tomorrow",\n                                height=360, sizing_mode="stretch_width")\nbouton = pn.widgets.Button(name="\u25b6 V\xe9rifier", button_type="primary", width=150)\nbouton_reset = pn.widgets.Button(name="\u21ba R\xe9initialiser", button_type="default",\n                                 width=150)\nbouton_sol = pn.widgets.Toggle(name="Voir la solution", button_type="warning",\n                               width=160)\nfeedback = pn.pane.Markdown(sizing_mode="stretch_width")\n\nexo_head = pn.pane.HTML(sizing_mode="stretch_width")\ntitlebar = pn.pane.HTML(sizing_mode="stretch_width")\nprogress = pn.pane.HTML()\n\n\ndef _titlebar_html(eid):\n    n = next((i for i, e in enumerate(EXERCICES, 1) if e["id"] == eid), 1)\n    return ("<div class='editor-titlebar'>"\n            "<span class='dot dot-r'></span><span class='dot dot-y'></span>"\n            "<span class='dot dot-g'></span>"\n            f"<span class='fname'>exercice_{n:02d}.py</span></div>")\n\n\ndef _exo_head_html(ex):\n    badge, label = _split_titre(ex["titre"])\n    avance = ex.get("niveau") == "avance"\n    tag = ("<span class='tag-avance'>Avanc\xe9 \u2605\u2605\u2605</span>" if avance\n           else "<span class='tag-base'>Base \u2605</span>")\n    badge_html = (f"<span class='exo-badge'>{_html.escape(badge)}</span>"\n                  if badge else "")\n    return ("<div class='exo-head' style='display:flex;align-items:center;gap:12px'>"\n            f"{badge_html}"\n            f"<span class='exo-h-title'>{_html.escape(label)}</span>"\n            f"<span style='flex:1 1 auto'></span>{tag}</div>")\n\n\ndef maj_progress():\n    pct = round(100 * len(solved) / TOTAL)\n    progress.object = (\n        "<div class='prog-wrap'>"\n        f"<div class='prog-pill'>{len(solved)} / {TOTAL} r\xe9ussis</div>"\n        f"<div class='prog-track'><div class='prog-fill' style='width:{pct}%'></div></div>"\n        "</div>")\n\n\n# --- Cartes de la sidebar --------------------------------------------------- #\n# Une carte = Row[badge | bouton-label | pastille statut], css togglee a l'execution.\n# Bokeh 3.x rend chaque widget dans son propre shadow root : le CSS global\n# (.exo-card .bk-btn) ne traverse PAS ces frontieres. On injecte donc le style\n# directement dans le shadow root de chaque composant via stylesheets=[...].\ncartes = {}     # eid -> pn.Row\n_boutons_sb = {}\n_stats_sb = {}  # eid -> pn.pane.HTML (pastille statut)\n\n# Pastilles statut : styles INLINE (le selecteur .exo-card.ok .exo-stat ne traverse\n# pas le shadow root du pane HTML - on change donc directement le contenu du pane).\n_STAT_BASE = ("width:20px;height:20px;border-radius:99px;"\n              "border:2px solid #d2d7e4;display:flex;align-items:center;"\n              "justify-content:center;font-size:12px;color:transparent")\n_STAT_OK = ("width:20px;height:20px;border-radius:99px;"\n            "border:2px solid #1b8a52;background:#1b8a52;color:#fff;"\n            "display:flex;align-items:center;justify-content:center;font-size:12px")\n_STAT_VIDE = f"<div style='{_STAT_BASE}'>\u2713</div>"\n_STAT_PLEIN = f"<div style='{_STAT_OK}'>\u2713</div>"\n\n# Style injecte dans le shadow root de la Row (carte) : fixe les flex des enfants.\nROW_SHEET = """\n:host { align-items: center; }\n.bk-panel-models-markup-HTML { flex: 0 0 auto !important; }\n.bk-panel-models-widgets-Button { flex: 1 1 auto !important; min-width: 0 !important; }\n"""\n\n# Style injecte dans le shadow root du Button-label : transparent, titre sur 2 lignes (lisible).\nBTN_SHEET = """\n:host { width: 100%; min-width: 0; }\n.bk-btn, .bk-btn-default {\n  background: transparent !important; border: none !important; box-shadow: none !important;\n  color: #1b2030 !important; text-align: left !important;\n  font-weight: 600 !important; font-size: 14px !important;\n  padding: 6px 4px !important; line-height: 1.38 !important;\n  display: block !important; width: 100% !important; max-width: 100% !important;\n  min-width: 0 !important;\n  white-space: normal !important; overflow-wrap: break-word !important; word-break: normal !important;\n}\n.bk-btn:hover, .bk-btn-default:hover { background: transparent !important; color: #03224C !important; }\n"""\n\n\ndef _make_carte(ex):\n    badge, label = _split_titre(ex["titre"])\n    b = pn.widgets.Button(name=label, button_type="default", sizing_mode="stretch_width",\n                          stylesheets=[BTN_SHEET])\n    b.on_click(lambda evt, eid=ex["id"]: select(eid))\n    _boutons_sb[ex["id"]] = b\n    stat = pn.pane.HTML(_STAT_VIDE, width=26)\n    _stats_sb[ex["id"]] = stat\n    badge_pane = pn.pane.HTML(f"<div class='exo-badge-sb'>{_html.escape(badge or '\u2022')}</div>",\n                              width=46)\n    row = pn.Row(badge_pane, b, stat, css_classes=["exo-card"],\n                 stylesheets=[ROW_SHEET], sizing_mode="stretch_width")\n    cartes[ex["id"]] = row\n    return row\n\n\ndef _maj_cartes():\n    for eid, row in cartes.items():\n        cls = ["exo-card"]\n        if eid in solved:\n            cls.append("ok")\n        if eid == etat["id"]:\n            cls.append("actif")\n        row.css_classes = cls\n        _stats_sb[eid].object = _STAT_PLEIN if eid in solved else _STAT_VIDE\n\n\n# --- Selection / verification ---------------------------------------------- #\ndef select(eid):\n    etat["id"] = eid\n    ex = exercice_par_id(eid)\n    exo_head.object = _exo_head_html(ex)\n    consigne.object = ex["consigne"]\n    editeur.value = ex["starter"]\n    titlebar.object = _titlebar_html(eid)\n    feedback.object = ""\n    bouton_sol.value = False\n    _maj_cartes()\n\n\ndef on_verifier(event):\n    eid = etat["id"]\n    ex = exercice_par_id(eid)\n    ok, md = verifier(ex, editeur.value)\n    feedback.object = md\n    if ok and eid not in solved:\n        solved.add(eid)\n        _maj_cartes()\n        maj_progress()\n\n\ndef on_reset(event):\n    ex = exercice_par_id(etat["id"])\n    editeur.value = ex["starter"]\n    feedback.object = ""\n    bouton_sol.value = False\n\n\ndef on_solution(event):\n    ex = exercice_par_id(etat["id"])\n    editeur.value = ex["solution"].strip() if bouton_sol.value else ex["starter"]\n\n\nbouton.on_click(on_verifier)\nbouton_reset.on_click(on_reset)\nbouton_sol.param.watch(on_solution, "value")\n\n\n# --- Assemblage de la sidebar ---------------------------------------------- #\nsidebar_items = [\n    pn.pane.HTML("<div class='sb-title'>Parcours d'exercices</div>"\n                 "<div class='sb-sub'>Finance durable &amp; ESG</div>"),\n]\n_base = [e for e in EXERCICES if e.get("niveau") != "avance"]\n_avance = [e for e in EXERCICES if e.get("niveau") == "avance"]\nif _base:\n    sidebar_items.append(pn.pane.HTML("<div class='section-head'>Exercices de base \u2605</div>"))\n    sidebar_items += [_make_carte(e) for e in _base]\nif _avance:\n    sidebar_items.append(pn.pane.HTML("<div class='section-head'>Exercices avanc\xe9s \u2605\u2605\u2605</div>"))\n    sidebar_items += [_make_carte(e) for e in _avance]\n\nsidebar = pn.Column(*sidebar_items, css_classes=["sidebar"],\n                    sizing_mode="stretch_width")\n\n# --- En-tete ---------------------------------------------------------------- #\nheader = pn.Row(\n    pn.pane.HTML(\n        "<div class='hdr-sub'>TgMaster University \xb7 B3 - AFE</div>"\n        "<div class='hdr-title'>Exercices Python - Finance durable &amp; ESG</div>"),\n    pn.HSpacer(),\n    progress,\n    pn.pane.HTML(\n        "<a href='https://tigi-prof-tigi.github.io/tgmaster-afe-python/' style='margin-left:14px;padding:6px 13px;border:1px solid #cfd8e6;border-radius:8px;color:#03224C;text-decoration:none;font-weight:600;font-size:13px;white-space:nowrap;background:#fff'>Accueil</a>"),\n    css_classes=["app-header"], sizing_mode="stretch_width",\n)\n\n# --- Panneau principal ------------------------------------------------------ #\neditor_win = pn.Column(titlebar, editeur, css_classes=["editor-window"],\n                       sizing_mode="stretch_width")\nmain = pn.Column(\n    exo_head,\n    consigne,\n    editor_win,\n    pn.Row(bouton, bouton_reset, bouton_sol),\n    pn.pane.HTML("<div style='font-weight:700;color:#03224C;margin-top:6px;font-size:15px'>R\xe9sultat</div>"),\n    pn.Column(feedback, css_classes=["feedback-card"], sizing_mode="stretch_width"),\n    css_classes=["main-panel"], sizing_mode="stretch_width",\n)\n\nbody = pn.Row(sidebar, main, css_classes=["body-row"],\n              sizing_mode="stretch_width")\napp = pn.Column(header, body, sizing_mode="stretch_width", max_width=1240)\n\n# Etat initial\nmaj_progress()\nselect(etat["id"])\n\napp.servable(title="Exercices Python - AFE 18")\n\n\nawait write_doc()
  `

  try {
    const [docs_json, render_items, root_ids] = await self.pyodide.runPythonAsync(code)
    self.postMessage({
      type: 'render',
      docs_json: docs_json,
      render_items: render_items,
      root_ids: root_ids
    })
  } catch(e) {
    const traceback = `${e}`
    const tblines = traceback.split('\n')
    self.postMessage({
      type: 'status',
      msg: tblines[tblines.length-2]
    });
    throw e
  }
}

self.onmessage = async (event) => {
  const msg = event.data
  if (msg.type === 'rendered') {
    self.pyodide.runPythonAsync(`
    from panel.io.state import state
    from panel.io.pyodide import _link_docs_worker

    _link_docs_worker(state.curdoc, sendPatch, setter='js')
    `)
  } else if (msg.type === 'patch') {
    self.pyodide.globals.set('patch', msg.patch)
    self.pyodide.runPythonAsync(`
    from panel.io.pyodide import _convert_json_patch
    state.curdoc.apply_json_patch(_convert_json_patch(patch), setter='js')
    `)
    self.postMessage({type: 'idle'})
  } else if (msg.type === 'location') {
    self.pyodide.globals.set('location', msg.location)
    self.pyodide.runPythonAsync(`
    import json
    from panel.io.state import state
    from panel.util import edit_readonly
    if state.location:
        loc_data = json.loads(location)
        with edit_readonly(state.location):
            state.location.param.update({
                k: v for k, v in loc_data.items() if k in state.location.param
            })
    `)
  }
}

startApplication()